const queryClient = new QueryClient();

const cx = (...items: Array<string | false | undefined>) => items.filter(Boolean).join(' ');
const fmt = (date?: string) => date ? new Intl.DateTimeFormat('en', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }).format(new Date(date)) : '—';
const titleCase = (value?: string) => (value || 'unknown').replace(/_/g, ' ').replace(/\b\w/g, (m) => m.toUpperCase());

function Brand({ compact = false }: { compact?: boolean }) {
  return <Link href="/" className="flex items-center gap-3" data-testid="link-brand">
    <span className={cx('flex items-center overflow-hidden rounded-lg bg-black', compact ? 'h-8 w-12' : 'h-9 w-[92px]')}>
      <img src={deltaLogo} alt="DELTA" className="h-full w-full object-contain" />
    </span>
  </Link>;
}

function Button({ children, className, variant = 'primary', ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'ghost' | 'subtle' | 'outline' }) {
  return <button className={cx(
    'inline-flex items-center justify-center gap-2 rounded-full px-4 py-2.5 text-sm font-semibold transition duration-200 disabled:cursor-not-allowed disabled:opacity-40',
    variant === 'primary' && 'bg-primary text-primary-foreground hover:-translate-y-0.5 hover:bg-zinc-800',
    variant === 'outline' && 'border border-border bg-card text-foreground hover:border-primary/40 hover:bg-secondary',
    variant === 'ghost' && 'text-muted-foreground hover:bg-secondary hover:text-foreground',
    variant === 'subtle' && 'bg-secondary text-foreground hover:bg-secondary/75',
    className,
  )} {...props}>{children}</button>;
}

function Badge({ children, tone = 'default' }: { children: ReactNode; tone?: 'default' | 'orange' | 'yellow' | 'green' | 'red' | 'muted' }) {
  const tones = {
    default: 'border-border bg-secondary text-muted-foreground',
    orange: 'border-orange-200 bg-orange-50 text-orange-700',
    yellow: 'border-violet-200 bg-violet-50 text-violet-700',
    green: 'border-emerald-200 bg-emerald-50 text-emerald-700',
    red: 'border-red-200 bg-red-50 text-red-700',
    muted: 'border-border/70 bg-background text-muted-foreground',
  };
  return <span className={cx('inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1.5 font-mono text-[10px] uppercase tracking-[.12em]', tones[tone])}>{children}</span>;
}

function StatusDot({ tone = 'orange' }: { tone?: 'orange' | 'green' | 'yellow' | 'red' | 'muted' }) {
  return <span className={cx('pulse-dot h-1.5 w-1.5 rounded-full', tone === 'orange' && 'bg-primary', tone === 'green' && 'bg-emerald-300', tone === 'yellow' && 'bg-accent', tone === 'red' && 'bg-red-300', tone === 'muted' && 'bg-muted-foreground')} />;
}

function PublicHeader() {
  const [open, setOpen] = useState(false);
  const nav = [['Platform', '/platform'], ['Agents', '/agents'], ['Workflows', '/workflows'], ['Enterprise', '/enterprise'], ['Security', '/security']];
  return <header className="sticky top-0 z-50 border-b border-border/70 bg-background/90 backdrop-blur-xl">
    <div className="mx-auto flex h-16 max-w-7xl items-center justify-between px-5 lg:px-8">
      <Brand />
      <nav className="hidden items-center gap-7 md:flex">
        {nav.map(([label, href]) => <Link key={href} href={href} className="text-xs font-semibold text-muted-foreground transition hover:text-foreground" data-testid={`link-nav-${label.toLowerCase()}`}>{label}</Link>)}
      </nav>
      <div className="hidden items-center gap-3 md:flex">
        <Link href="/resources" className="text-xs font-semibold text-muted-foreground hover:text-foreground" data-testid="link-resources">Resources</Link>
        <Link href="/app" className="rounded-full bg-primary px-4 py-2 text-xs font-bold text-primary-foreground transition hover:-translate-y-0.5" data-testid="link-open-workspace">Open workspace <ArrowRight className="ml-1 inline h-3.5 w-3.5" /></Link>
      </div>
      <button className="md:hidden" onClick={() => setOpen(!open)} aria-label="Toggle menu" data-testid="button-mobile-menu">{open ? <X /> : <Menu />}</button>
    </div>
    {open && <div className="border-t border-border bg-card px-5 py-4 md:hidden">
      {nav.map(([label, href]) => <Link key={href} href={href} onClick={() => setOpen(false)} className="block border-b border-border/60 py-3 text-sm" data-testid={`link-mobile-${label.toLowerCase()}`}>{label}</Link>)}
      <Link href="/app" className="mt-4 block rounded-md bg-primary px-4 py-3 text-center text-sm font-bold text-primary-foreground" data-testid="link-mobile-workspace">Open demo workspace</Link>
    </div>}
  </header>;
}

