const publicContent: Record<string, { eyebrow: string; title: string; lead: string; cards: Array<[string, string, string]> }> = {
  '/platform': { eyebrow: 'The DELTA system', title: 'Intelligence with a handoff, not a black box.', lead: 'Four layers keep the machine useful and the humans accountable: intelligence, orchestration, execution, and governance.', cards: [['Intelligence', 'Context becomes structured understanding.', 'Delta reads source material, finds signals, and names uncertainty instead of smoothing it over.'], ['Orchestration', 'The right agent moves at the right moment.', 'Lifecycle state determines what can run next, what must wait, and where human attention belongs.'], ['Execution', 'Outputs become work, not just prose.', 'Requirements, decisions, and implementation tasks stay connected as the operating record evolves.'], ['Governance', 'Control is part of the flow.', 'Approval gates, audit events, and data boundaries are visible by design.']] },
  '/agents': { eyebrow: 'The DELTA squad', title: 'Specialists that hand work to one another.', lead: 'Three focused agents carry the work between human control points. Each has a job, an output, and a visible state.', cards: [['Discovery agent', 'Collects signal into a brief.', 'Maps objectives, stakeholders, assumptions, open questions, risks, and requirements from source context.'], ['Analysis agent', 'Tests the shape of the work.', 'Finds ambiguity, conflicts, missing dependencies, risks, recommendations, and open decisions.'], ['Planning agent', 'Sequences the next move.', 'Turns validated requirements and approved decisions into an implementation plan with linked tasks.'], ['Work states', 'Working is not pretending.', 'Available, working, waiting, and output available are operational states — not conversational moods.']] },
  '/workflows': { eyebrow: 'Lifecycle control', title: 'A visible path from ambiguity to action.', lead: 'The live loop is Discover → Analyze → Approve → Plan. Design through Deploy are roadmap stages, not pretending to be live capabilities.', cards: [['LIVE / Discover', 'Collect and structure the signal.', 'Source inputs become objectives, stakeholders, assumptions, questions, risks, and requirements.'], ['LIVE / Analyze', 'Test the shape of the work.', 'The analysis agent surfaces conflicts, gaps, dependencies, and recommendations.'], ['LIVE / Approve', 'Put consequence in human hands.', 'Decision owners see the evidence and choose approve, request changes, reject, or escalate.'], ['LIVE / Plan', 'Sequence the next move.', 'A plan turns validated requirements into linked tasks and clear workstreams.'], ['ROADMAP / Design → Build', 'From blueprint to build.', 'Future stages will extend the operational record into design artifacts and delivery execution.'], ['ROADMAP / Quality → Govern → Deploy', 'The loop keeps widening.', 'Quality, governance, and deployment controls are intentionally marked as future stages.']] },
  '/enterprise': { eyebrow: 'Enterprise operating model', title: 'Give AI the work. Keep authority where it belongs.', lead: 'DELTA is designed for teams that cannot afford either blind automation or manual coordination theatre.', cards: [['Distributed context', 'One shared implementation record.', 'Teams can work from the same evidence without flattening expertise into a chat thread.'], ['Decision rights', 'Make ownership legible.', 'Every approval names who decided, when, and why.'], ['Operational rhythm', 'Move from meeting to momentum.', 'Agents create useful next states so people spend time on judgment, not transcription.']] },
  '/security': { eyebrow: 'Security & governance', title: 'Boundaries are a product feature.', lead: 'A trustworthy implementation system makes its controls visible at the moment the work happens.', cards: [['Human approvals', 'No consequential action without a named decision.', 'Approval objects carry status, timestamps, decision owner, and comment.'], ['Audit trail', 'Activity is part of the implementation record.', 'Agent work and human actions are recorded as events that teams can inspect.'], ['Traceability', 'Follow the thread end to end.', 'Objective, source, requirement, analysis, decision, task, and outcome stay linked.'], ['Data boundaries', 'Start with the context you choose.', 'Source inputs are explicit. The demo workspace is available without claiming an external identity connection.']] },
  '/resources': { eyebrow: 'Field notes', title: 'Practical material for the implementation edge.', lead: 'Short, opinionated resources for teams deciding how to introduce AI into consequential delivery work.', cards: [['Implementation brief', 'The first 30 days with DELTA.', 'A working sequence for selecting a project, defining decision rights, and creating a baseline record.'], ['Control point guide', 'Where humans should stay in the loop.', 'A checklist for approvals, exception paths, and escalation boundaries.'], ['Traceability primer', 'Make outcomes legible.', 'How to connect intent to tasks without building a document maze.']] },
  '/company': { eyebrow: 'The DELTA premise', title: 'Build systems that respect the difference between speed and judgment.', lead: 'We believe AI should reduce the distance between knowing and doing without erasing the people who own the consequences.', cards: [['Useful by default', 'Outputs should create the next move.', 'The test is not whether an agent sounds smart. It is whether the team can act with more clarity.'], ['Specific over spectacular', 'No vague automation promises.', 'We name the live capability, the human gate, and the roadmap boundary.'], ['Built with operators', 'The people closest to the work shape the system.', 'DELTA is designed around the actual texture of enterprise implementation.']] },
};

